"""Render as JSON Schema (draft 2020-12)."""

from __future__ import annotations

import json

from ..schema import (
    Array,
    Boolean,
    DataSchema,
    Entity,
    Field,
    Integer,
    Node,
    Null,
    Number,
    Object,
    String,
    Union,
    Unknown,
)

_DIALECT = "https://json-schema.org/draft/2020-12/schema"
_COMMENT = (
    "Generated by DataNyx. Contains no data values. Treat it as a description "
    "rather than a validator: for sampled sources, required fields and formats "
    "held for the data sampled; SQLite doesn't enforce declared column types; and "
    "names that looked like data are hidden behind additionalProperties."
)


def render_json_schema(schema: DataSchema) -> str:
    document: dict = {"$schema": _DIALECT, "$comment": _COMMENT}
    if len(schema.entities) == 1 and schema.entities[0].name is None:
        document.update(_entity(schema.entities[0]))
    else:
        document["$defs"] = {entity.name: _entity(entity) for entity in schema.entities}
    # ASCII-only output survives any terminal or file encoding.
    return json.dumps(document, indent=2, ensure_ascii=True)


def _entity(entity: Entity) -> dict:
    result = _node(entity.node)
    if entity.primary_key:
        result["x-primary-key"] = list(entity.primary_key)
    if entity.foreign_keys:
        result["x-foreign-keys"] = [
            {
                "columns": list(key.columns),
                "references": {
                    "table": key.referenced_entity,
                    "columns": list(key.referenced_columns),
                },
            }
            for key in entity.foreign_keys
        ]
    return result


def _field(field: Field) -> dict:
    result = _node(field.node)
    if field.native_type:
        result["x-native-type"] = field.native_type
    return result


def _node(node: Node) -> dict:
    if isinstance(node, Unknown):
        return {}
    if isinstance(node, Null):
        return {"type": "null"}
    if isinstance(node, Boolean):
        return {"type": "boolean"}
    if isinstance(node, Integer):
        return {"type": "integer"}
    if isinstance(node, Number):
        return {"type": "number"}
    if isinstance(node, String):
        return {"type": "string", "format": node.format} if node.format else {"type": "string"}
    if isinstance(node, Array):
        items = _node(node.items)
        return {"type": "array", "items": items} if items else {"type": "array"}
    if isinstance(node, Object):
        return _object(node)
    if isinstance(node, Union):
        return _union(node)
    raise TypeError(f"unhandled node: {type(node).__name__}")


def _object(node: Object) -> dict:
    result: dict = {"type": "object"}
    if node.fields:
        result["properties"] = {name: _field(field) for name, field in node.fields.items()}
        required = [name for name, field in node.fields.items() if field.required]
        if required:
            result["required"] = required
    if node.extra is not None:
        result["additionalProperties"] = _node(node.extra)
    # propertyNames applies to every key, so it would be false for named fields.
    if node.key_format and not node.fields:
        result["propertyNames"] = {"format": node.key_format}
    return result


def _union(node: Union) -> dict:
    options = [_node(option) for option in node.options]
    if all(set(option) == {"type"} for option in options):
        return {"type": [option["type"] for option in options]}
    return {"anyOf": options}
